html:
{#- Purchase Order print: Shyamji Group red and yellow. Plain tables only (the PDF maker is wkhtmltopdf). -#}
{%- macro money(value) -%}{{ frappe.utils.fmt_money(value or 0, 2) }}{%- endmacro -%}
{%- macro num(value, places=3) -%}{{ ("{:,.%sf}" % places).format(value or 0) }}{%- endmacro -%}
{%- set items = doc.items or [] -%}
{%- set has_quality = items | selectattr("quality") | list | length > 0 -%}
{%- set has_dimension = items | selectattr("dimension") | list | length > 0 -%}
{%- set has_avg_wt = items | selectattr("uom", "equalto", "Trip") | list | length > 0 -%}
{%- set has_oil = items | selectattr("rate_per_mt") | list | length > 0 -%}
{%- set pds_rates = [doc.quality_pds_rate_1, doc.quality_pds_rate_2, doc.quality_pds_rate_3] -%}
{%- set has_pds = pds_rates | select | list | length > 0 -%}
{#- the discount fields are hidden from the standard print layout, so their values are read here -#}
{%- set disc = (frappe.db.get_value("Purchase Order", doc.name, ["discount_amount", "additional_discount_percentage"], as_dict=True) if doc.name else None) or {} -%}
{%- set discount_amount = disc.get("discount_amount") or doc.discount_amount or 0 -%}
{%- set discount_pct = disc.get("additional_discount_percentage") or doc.additional_discount_percentage or 0 -%}
{%- set show_discount = discount_amount > 0 -%}
{%- set show_hamali = (doc.total_hamali or 0) > 0 -%}
{#- the Company name, logo and Group text are left off when Print Company Name is unticked (an older order with no value still prints them) -#}
{%- set show_company = (doc.print_company_name if doc.print_company_name is not none else 1) | int -%}
{%- set cols = 6 + (1 if has_quality else 0) + (1 if has_dimension else 0) + (1 if has_avg_wt else 0) -%}
<div class="po">

	<table class="po-head">
		<tr>
			{%- if show_company %}
			<td class="po-logo"><img src="/assets/ivri_od/images/shyamji_group_logo.jpg" alt="Shyamji Group"></td>
			<td class="po-company">
				<div class="po-company-name">{{ doc.company }}</div>
				<div class="po-company-sub">Shyamji Group</div>
			</td>
			{%- else %}
			<td class="po-company"></td>
			{%- endif %}
			<td class="po-title-box">
				<div class="po-title">PURCHASE ORDER</div>
				<div class="po-no">{{ doc.name }}</div>
				{%- if doc.docstatus == 0 %}<div class="po-status">DRAFT</div>{% elif doc.docstatus == 2 %}<div class="po-status">CANCELLED</div>{% endif %}
			</td>
		</tr>
	</table>
	<div class="po-bar"></div>
	<div class="po-bar-yellow"></div>

	<table class="po-two">
		<tr>
			<td class="po-box po-box-left">
				<div class="po-box-title">Supplier</div>
				<div class="po-strong">{{ doc.supplier_name or doc.supplier }}</div>
				{%- if doc.address_display %}<div class="po-small">{{ doc.address_display }}</div>{% endif %}
				{%- if doc.contact_display %}<div class="po-small">{{ doc.contact_display }}</div>{% endif %}
				{%- if doc.contact_mobile %}<div class="po-small">Mobile: {{ doc.contact_mobile }}</div>{% endif %}
			</td>
			<td class="po-gap"></td>
			<td class="po-box">
				<div class="po-box-title">Order Details</div>
				<table class="po-kv">
					<tr><td>Order Date</td><td>{{ frappe.utils.formatdate(doc.transaction_date) }}</td></tr>
					{%- if doc.schedule_date %}<tr><td>Required By</td><td>{{ frappe.utils.formatdate(doc.schedule_date) }}</td></tr>{% endif %}
					{%- if doc.payment_mode %}<tr><td>Payment Mode</td><td>{{ doc.payment_mode }}</td></tr>{% endif %}
					{%- if doc.delivery_type %}<tr><td>Delivery Type</td><td>{{ doc.delivery_type }}{% if doc.location_name %} - {{ doc.location_name }}{% endif %}</td></tr>{% endif %}
					{%- if doc.gunny_condition %}<tr><td>Gunny Condition</td><td>{{ doc.gunny_condition }}</td></tr>{% endif %}
					{%- if doc.dust_condition %}<tr><td>Dust Condition</td><td>{{ doc.dust_condition }}</td></tr>{% endif %}
				</table>
			</td>
		</tr>
	</table>

	{%- if doc.vehicle_ownership %}
	<table class="po-two po-vehicle">
		<tr>
			<td class="po-box">
				<div class="po-box-title">Vehicle</div>
				<table class="po-kv po-kv-wide">
					<tr>
						<td>Ownership</td><td>{{ doc.vehicle_ownership }}</td>
						{%- if doc.vehicle_ownership == "Transport Vehicle" and doc.transporter %}<td>Transporter</td><td>{{ doc.transporter }}</td>{% else %}<td></td><td></td>{% endif %}
					</tr>
					{%- if doc.vehicle_ownership == "Transport Vehicle" and (doc.vehicle_number or doc.driver) %}
					<tr><td>Vehicle No.</td><td>{{ doc.vehicle_number or "" }}</td>{% if doc.driver %}<td>Driver</td><td>{{ doc.driver }}</td>{% else %}<td></td><td></td>{% endif %}</tr>
					{%- endif %}
				</table>
			</td>
		</tr>
	</table>
	{%- endif %}

	<table class="po-items">
		<thead>
			<tr>
				<th class="c">#</th>
				<th class="l">Item</th>
				{%- if has_quality %}<th class="l">Quality</th>{% endif %}
				{%- if has_dimension %}<th class="c">Dimension (mm)</th>{% endif %}
				<th class="r">Quantity</th>
				<th class="c">UOM</th>
				{%- if has_avg_wt %}<th class="r">Avg Wt (MT)</th>{% endif %}
				{%- if has_oil %}<th class="r">Rate / MT</th><th class="r">Oil %</th>{% endif %}
				<th class="r">Rate</th>
				<th class="r">Amount</th>
			</tr>
		</thead>
		<tbody>
			{%- for row in items %}
			<tr>
				<td class="c">{{ loop.index }}</td>
				<td class="l"><span class="po-strong">{{ row.item_name or row.item_code }}</span></td>
				{%- if has_quality %}<td class="l">{{ row.quality or "" }}</td>{% endif %}
				{%- if has_dimension %}<td class="c">{{ row.dimension or "" }}</td>{% endif %}
				<td class="r">{{ num(row.qty) }}</td>
				<td class="c">{{ row.uom }}</td>
				{%- if has_avg_wt %}<td class="r">{% if row.uom == "Trip" %}{{ num(row.avg_wt, 2) }}{% endif %}</td>{% endif %}
				{%- if has_oil %}<td class="r">{% if row.rate_per_mt %}{{ money(row.rate_per_mt) }}{% endif %}</td><td class="r">{% if row.rate_per_mt %}{{ num(row.oil_percentage, 2) }} %{% endif %}</td>{% endif %}
				<td class="r">{{ money(row.rate) }}</td>
				<td class="r">{{ money(row.amount) }}</td>
			</tr>
			{%- endfor %}
		</tbody>
	</table>

	<table class="po-two po-after">
		<tr>
			<td class="po-after-left">
				{%- if has_pds %}
				<div class="po-box-title">Quality PDS Rates</div>
				<table class="po-kv">
					{%- for rate in pds_rates if rate %}<tr><td>PDS Rate {{ loop.index }}</td><td>{{ money(rate) }}</td></tr>{% endfor %}
				</table>
				{%- endif %}
			</td>
			<td class="po-gap"></td>
			<td class="po-after-right">
				<table class="po-totals">
					<tr><td>Total Quantity</td><td class="r">{{ num(doc.total_qty) }}</td></tr>
					<tr><td>Total (INR)</td><td class="r">{{ money(doc.total) }}</td></tr>
					{%- if show_discount %}
					<tr><td>Cash Discount{% if discount_pct %} ({{ num(discount_pct, 2) }}%){% endif %}</td><td class="r">- {{ money(discount_amount) }}</td></tr>
					<tr><td>Grand Total (INR)</td><td class="r">{{ money(doc.grand_total) }}</td></tr>
					{%- endif %}
					{%- if show_hamali %}
					<tr><td>Less: Hamali</td><td class="r">- {{ money(doc.total_hamali) }}</td></tr>
					{%- endif %}
					<tr class="po-final"><td>Total Final Amount (INR)</td><td class="r">{{ money(doc.total_final_amount) }}</td></tr>
				</table>
			</td>
		</tr>
	</table>

	<div class="po-words"><span>Amount in words:</span> {{ frappe.utils.money_in_words(doc.total_final_amount or 0, "INR") }}</div>

	{%- if doc.terms %}
	<div class="po-terms">
		<div class="po-box-title">Terms and Conditions</div>
		<div class="po-small">{{ doc.terms }}</div>
	</div>
	{%- endif %}

	<table class="po-sign">
		<tr>
			<td><div class="po-line"></div>Prepared By</td>
			<td><div class="po-line"></div>Checked By</td>
			<td><div class="po-line"></div>Authorised Signatory{% if show_company %}<br><span class="po-small">for {{ doc.company }}</span>{% endif %}</td>
		</tr>
	</table>

	<div class="po-foot">This is a computer generated Purchase Order.</div>
</div>

css:
/* Colour is only an accent: every box, heading and total is also drawn with borders, weight and size, so a black and white copy reads the same. */
.print-format { max-width: none; padding: 0; margin-top: 6mm; margin-bottom: 8mm; margin-left: 8mm; margin-right: 8mm; font-size: 11px; }
.po { font-family: Arial, Helvetica, sans-serif; font-size: 11px; color: #111; -webkit-print-color-adjust: exact; print-color-adjust: exact; }
.po table { width: 100%; border-collapse: collapse; }
.po td, .po th { vertical-align: top; }
.po-strong { font-weight: bold; }
.po-small { font-size: 10px; color: #333; margin-top: 2px; }
.po .l { text-align: left; } .po .c { text-align: center; } .po .r { text-align: right; }
.po-head td { vertical-align: middle; }
.po-logo { width: 95px; padding-bottom: 6px; }
.po-logo img { width: 88px; height: auto; }
.po-company-name { font-size: 20px; font-weight: bold; color: #9c0a05; text-transform: uppercase; }
.po-company-sub { font-size: 11px; color: #333; letter-spacing: 2px; margin-top: 3px; }
.po-title-box { width: 240px; text-align: right; white-space: nowrap; }
.po-title { font-size: 17px; font-weight: bold; color: #111; letter-spacing: 1px; border-bottom: 2px solid #9c0a05; padding-bottom: 2px; display: inline-block; }
.po-no { font-size: 13px; font-weight: bold; margin-top: 4px; }
.po-status { display: inline-block; margin-top: 4px; padding: 1px 8px; border: 2px solid #111; color: #111; font-size: 10px; font-weight: bold; }
.po-bar { height: 4px; background: #9c0a05; }
.po-bar-yellow { height: 2px; background: #f5c400; margin-top: 1px; margin-bottom: 10px; border-bottom: 1px solid #111; }
.po-two { margin-bottom: 8px; }
.po-gap { width: 10px; }
.po-box { border: 1px solid #333; padding: 6px 8px; }
.po-box-title { font-size: 10px; font-weight: bold; color: #111; text-transform: uppercase; letter-spacing: 1px; border-bottom: 1px solid #333; padding-bottom: 2px; margin-bottom: 5px; }
.po-kv td { padding: 2px 4px 2px 0; }
.po-kv td:nth-child(odd) { color: #333; width: 105px; }
.po-kv td:nth-child(even) { font-weight: bold; }
.po-kv-wide td:nth-child(odd) { width: 90px; }
.po-items { margin-top: 4px; border: 1.5px solid #111; }
.po-items th { background: #e6e6e6; color: #111; padding: 6px 6px; font-size: 10px; text-transform: uppercase; border: 1px solid #333; border-bottom: 2px solid #111; }
.po-items td { padding: 6px 6px; border: 1px solid #777; }
.po-items tr { page-break-inside: avoid; }
.po-after { margin-top: 8px; page-break-inside: avoid; }
.po-after-left { width: 48%; }
.po-after-right { width: 50%; }
.po-totals { border: 1px solid #333; }
.po-totals td { padding: 5px 8px; border-bottom: 1px solid #999; }
.po-totals .po-final td { background: #f4e9b8; color: #111; font-weight: bold; font-size: 12px; border-top: 3px double #111; border-bottom: 3px double #111; }
.po-words { margin-top: 8px; padding: 6px 8px; border: 1px solid #333; border-left: 5px solid #9c0a05; font-weight: bold; }
.po-words span { color: #111; text-transform: uppercase; font-size: 10px; letter-spacing: 1px; }
.po-terms { margin-top: 10px; page-break-inside: avoid; }
.po-sign { margin-top: 38px; page-break-inside: avoid; }
.po-sign td { width: 33%; text-align: center; padding: 0 14px; font-weight: bold; font-size: 10px; }
.po-line { border-top: 1px solid #111; margin-bottom: 4px; }
.po-foot { margin-top: 16px; padding-top: 4px; border-top: 3px solid #9c0a05; text-align: center; font-size: 9px; color: #333; }

html:
{#- Purchase Receipt print: the same format as the Purchase Order print (Shyamji Group red and yellow). Plain tables only (the PDF maker is wkhtmltopdf). -#}
{%- macro money(value) -%}{{ frappe.utils.fmt_money(value or 0, 2) }}{%- endmacro -%}
{%- macro num(value, places=3) -%}{{ ("{:,.%sf}" % places).format(value or 0) }}{%- endmacro -%}
{%- set items = doc.items or [] -%}
{%- set has_quality = items | selectattr("quality") | list | length > 0 -%}
{%- set has_dimension = items | selectattr("dimension") | list | length > 0 -%}
{%- set has_avg_wt = items | selectattr("uom", "equalto", "Trip") | list | length > 0 -%}
{%- set has_oil = items | selectattr("rate_per_mt") | list | length > 0 -%}
{%- set orders = items | map(attribute="purchase_order") | select | unique | list -%}
{%- set pds = [(1, doc.quality_pds_qty_1, doc.quality_pds_rate_1, doc.quality_pds_pct_1), (2, doc.quality_pds_qty_2, doc.quality_pds_rate_2, doc.quality_pds_pct_2), (3, doc.quality_pds_qty_3, doc.quality_pds_rate_3, doc.quality_pds_pct_3)] | selectattr(1) | list -%}
{%- set discount_amount = doc.discount_amount or 0 -%}
{%- set discount_pct = doc.additional_discount_percentage or 0 -%}
{%- set show_discount = discount_amount > 0 -%}
{%- set show_hamali = (doc.total_hamali or 0) > 0 -%}
{#- the Company name, logo and Group text are left off when Print Company Name is unticked (an older receipt with no value still prints them) -#}
{%- set show_company = (doc.print_company_name if doc.print_company_name is not none else 1) | int -%}
<div class="po">

	<table class="po-head">
		<tr>
			{%- if show_company %}
			<td class="po-logo"><img src="/assets/ivri_od/images/shyamji_group_logo.jpg" alt="Shyamji Group"></td>
			<td class="po-company">
				<div class="po-company-name">{{ doc.company }}</div>
				<div class="po-company-sub">Shyamji Group</div>
			</td>
			{%- else %}
			<td class="po-company"></td>
			{%- endif %}
			<td class="po-title-box">
				<div class="po-title">PURCHASE RECEIPT</div>
				<div class="po-no">{{ doc.name }}</div>
				{%- if doc.docstatus == 0 %}<div class="po-status">DRAFT</div>{% elif doc.docstatus == 2 %}<div class="po-status">CANCELLED</div>{% elif doc.receipt_status %}<div class="po-status">{{ doc.receipt_status | upper }}</div>{% endif %}
			</td>
		</tr>
	</table>
	<div class="po-bar"></div>
	<div class="po-bar-yellow"></div>

	<table class="po-two">
		<tr>
			<td class="po-box po-box-left">
				<div class="po-box-title">Supplier</div>
				<div class="po-strong">{{ doc.supplier_name or doc.supplier or "" }}</div>
				{%- if doc.address_display %}<div class="po-small">{{ doc.address_display }}</div>{% endif %}
				{%- if doc.contact_display %}<div class="po-small">{{ doc.contact_display }}</div>{% endif %}
				{%- if doc.contact_mobile %}<div class="po-small">Mobile: {{ doc.contact_mobile }}</div>{% endif %}
				{%- if doc.supplier_delivery_note %}<div class="po-small">Supplier Delivery Note: {{ doc.supplier_delivery_note }}</div>{% endif %}
			</td>
			<td class="po-gap"></td>
			<td class="po-box">
				<div class="po-box-title">Receipt Details</div>
				<table class="po-kv">
					<tr><td>Receipt Date</td><td>{{ frappe.utils.formatdate(doc.posting_date) }}</td></tr>
					{%- if orders %}<tr><td>Purchase Order</td><td>{{ orders | join(", ") }}</td></tr>{% endif %}
					{%- if doc.payment_mode %}<tr><td>Payment Mode</td><td>{{ doc.payment_mode }}</td></tr>{% endif %}
					{%- if doc.delivery_type %}<tr><td>Delivery Type</td><td>{{ doc.delivery_type }}{% if doc.location_name %} - {{ doc.location_name }}{% endif %}</td></tr>{% endif %}
					{%- if doc.gunny_condition %}<tr><td>Gunny Condition</td><td>{{ doc.gunny_condition }}</td></tr>{% endif %}
					{%- if doc.dust_condition %}<tr><td>Dust Condition</td><td>{{ doc.dust_condition }}</td></tr>{% endif %}
				</table>
			</td>
		</tr>
	</table>

	{%- if doc.vehicle_ownership %}
	<table class="po-two po-vehicle">
		<tr>
			<td class="po-box">
				<div class="po-box-title">Vehicle</div>
				<table class="po-kv po-kv-wide">
					<tr>
						<td>Ownership</td><td>{{ doc.vehicle_ownership }}</td>
						{%- if doc.vehicle_ownership == "Transport Vehicle" and doc.transporter %}<td>Transporter</td><td>{{ doc.transporter }}</td>{% else %}<td></td><td></td>{% endif %}
					</tr>
					{%- if doc.vehicle_ownership == "Transport Vehicle" and (doc.vehicle_number or doc.driver) %}
					<tr><td>Vehicle No.</td><td>{{ doc.vehicle_number or "" }}</td>{% if doc.driver %}<td>Driver</td><td>{{ doc.driver }}</td>{% else %}<td></td><td></td>{% endif %}</tr>
					{%- endif %}
					{%- if doc.vehicle_ownership == "Transport Vehicle" and doc.freight_charges %}
					<tr><td>Freight Charges</td><td>{{ money(doc.freight_charges) }}</td><td></td><td></td></tr>
					{%- endif %}
				</table>
			</td>
		</tr>
	</table>
	{%- endif %}

	<table class="po-items">
		<thead>
			<tr>
				<th class="c">#</th>
				<th class="l">Item</th>
				{%- if has_quality %}<th class="l">Quality</th>{% endif %}
				{%- if has_dimension %}<th class="c">Dimension (mm)</th>{% endif %}
				<th class="r">Ordered</th>
				<th class="r">Received</th>
				<th class="c">UOM</th>
				{%- if has_avg_wt %}<th class="r">Avg Wt (MT)</th>{% endif %}
				{%- if has_oil %}<th class="r">Rate / MT</th><th class="r">Oil % (Benchmark)</th><th class="r">Actual Oil %</th><th class="r">Adjusted Rate / MT</th>{% endif %}
				<th class="r">Rate</th>
				<th class="r">Amount</th>
			</tr>
		</thead>
		<tbody>
			{%- for row in items %}
			<tr>
				<td class="c">{{ loop.index }}</td>
				<td class="l"><span class="po-strong">{{ row.item_name or row.item_code }}</span></td>
				{%- if has_quality %}<td class="l">{{ row.quality or "" }}</td>{% endif %}
				{%- if has_dimension %}<td class="c">{{ row.dimension or "" }}</td>{% endif %}
				<td class="r">{% if row.ordered_qty %}{{ num(row.ordered_qty) }}{% endif %}</td>
				<td class="r">{{ num(row.qty) }}</td>
				<td class="c">{{ row.uom }}</td>
				{%- if has_avg_wt %}<td class="r">{% if row.uom == "Trip" %}{{ num(row.avg_wt, 2) }}{% endif %}</td>{% endif %}
				{%- if has_oil %}<td class="r">{% if row.rate_per_mt %}{{ money(row.rate_per_mt) }}{% endif %}</td><td class="r">{% if row.rate_per_mt %}{{ num(row.oil_percentage, 2) }} %{% endif %}</td><td class="r">{% if row.actual_oil_percentage %}{{ num(row.actual_oil_percentage, 2) }} %{% endif %}</td><td class="r">{% if row.oil_rate_per_mt %}{{ money(row.oil_rate_per_mt) }}{% endif %}</td>{% endif %}
				<td class="r">{{ money(row.rate) }}</td>
				<td class="r">{{ money(row.amount) }}</td>
			</tr>
			{%- endfor %}
		</tbody>
	</table>

	<table class="po-two po-after">
		<tr>
			<td class="po-after-left">
