html:
{#- Two layouts in one format: Balangir has its own sheet, every other district uses the second one.
    Order: the hired vehicles, their TOTAL, then the own vehicles (under an undertaking, no voucher or payment mode) with their TOTAL,
    then G.TOTAL, TOTAL VOUCHER and the two signature lines. The title and the column heads are printed once, on the first page.
    The rows are cut into pages here (not by the PDF maker), so a row is never split between two pages. -#}
{%- set bal = ((doc.district or "") | trim | lower == "balangir") -%}
{%- set ac = (doc.district or "") | trim | upper -%}
{%- set mill = (doc.mill_name_and_place or (doc.miller or "").rsplit("(", 1)[0]) | trim | upper -%}
{%- set season_text = (doc.season or "") | lower -%}
{%- set crop = " (KHARIF)" if season_text.startswith("kharif") else (" (RABI)" if season_text.startswith("rabi") else "") -%}
{%- set hired = vehicle_lines(doc) | rejectattr("vehicle_type", "equalto", "Own Vehicle") | list -%}
{%- set own = vehicle_lines(doc) | selectattr("vehicle_type", "equalto", "Own Vehicle") | list -%}
{%- set h_qty = hired | sum(attribute="qty") -%}
{%- set h_amt = hired | sum(attribute="amount") -%}
{%- set o_qty = own | sum(attribute="qty") -%}
{%- set o_amt = own | sum(attribute="amount") -%}
{%- set cl_n = 'c' if bal else 'r' -%}
{%- set first_page = 33 if bal else 30 -%}
{%- set next_page = 37 -%}
{%- set summary_cost = 6 -%}
{%- set seq = namespace(list=[]) -%}
{%- for row in hired -%}{%- set seq.list = seq.list + [{"k": "h", "r": row, "cost": [1, (((row.voucher_no or "") | length) / 24) | round(0, "ceil") | int] | max}] -%}{%- endfor -%}
{%- set seq.list = seq.list + [{"k": "sub", "q": h_qty, "a": h_amt, "cost": 1.5}] -%}
{%- set own_block = own | length + 1.5 + summary_cost -%}
{%- for row in own -%}{%- set seq.list = seq.list + [{"k": "o", "r": row, "cost": 1, "need": own_block if loop.first else 0}] -%}{%- endfor -%}
{%- if own -%}{%- set seq.list = seq.list + [{"k": "sub", "q": o_qty, "a": o_amt, "cost": 1.5}] -%}{%- endif -%}
{%- set ns = namespace(pages=[], cur=[], used=0, limit=first_page) -%}
{%- for it in seq.list -%}
	{%- if ns.cur and ns.used + (it.need or it.cost) > ns.limit -%}
		{%- set ns.pages = ns.pages + [ns.cur] -%}
		{%- set ns.cur = [] -%}
		{%- set ns.used = 0 -%}
		{%- set ns.limit = next_page -%}
	{%- endif -%}
	{%- set ns.cur = ns.cur + [it] -%}
	{%- set ns.used = ns.used + it.cost -%}
{%- endfor -%}
{%- if ns.used + summary_cost > ns.limit + 3 -%}
	{%- set ns.pages = ns.pages + [ns.cur] -%}
	{%- set ns.cur = [] -%}
{%- endif -%}
{%- set ns.pages = ns.pages + [ns.cur] -%}
{%- for page in ns.pages %}
{%- set n_own = page | selectattr("k", "equalto", "o") | list | length -%}
{%- set tall = n_own >= 8 -%}
{%- set seen = namespace(own=false) %}
<div class="vws {{ 'vws-bal' if bal else 'vws-other' }}{% if not loop.last %} vws-break{% endif %}">
	<table>
		<colgroup><col style="width:7%"><col style="width:17%"><col style="width:15%"><col style="width:15%"><col style="width:20%"><col style="width:10%"><col style="width:16%"></colgroup>
		<tbody>
			{%- if loop.first %}
			<tr><th colspan="7" class="title"><b>VEHICLE WISE STATEMENT OF PADDY LIFTED FOR {{ doc.kms_title or doc.season }}{% if bal %}{{ crop }} {% else %} {% endif %}ALONG WITH VOUCHER DETAILS{% if not bal and ac %}<br>({{ ac }} A/C){% endif %}</b></th></tr>
			{%- if not bal %}
			<tr><th colspan="7" class="mill"><b>{{ mill }}{% if ac %} ({{ ac }} A/C){% endif %}</b></th></tr>
			{%- endif %}
			<tr class="head">
				<th><b>S.L NO</b></th><th><b>VEHICLE NO.</b></th><th><b>QUANTITY IN QUINTALS</b></th><th><b>AMOUNT IN RS</b></th><th><b>VOUCHER NO</b></th><th><b>PAYMENT<br>MODE</b></th><th><b>VEHICLE TYPE</b></th>
			</tr>
			{%- endif %}
			{%- for it in page %}
			{%- if it.k == "h" %}
			{%- set row = it.r %}
			<tr>
				<td class="c">{{ row.sl_no }}</td>
				<td class="{{ 'c' if bal else 'l' }}">{{ row.vehicle_no }}</td>
				<td class="{{ cl_n }}">{{ ("%.2f" | format(row.qty or 0)).rstrip("0").rstrip(".") }}</td>
				<td class="{{ cl_n }}">{{ "%.2f" | format(row.amount or 0) }}</td>
				<td class="c">{{ row.voucher_no or "" }}</td>
				<td class="c">{{ row.payment_mode or "CASH" }}</td>
				<td class="c">HIRED VEHICLE</td>
			</tr>
			{%- elif it.k == "o" %}
			{%- set row = it.r %}
			{%- if not tall and not seen.own %}
			<tr><th colspan="7" class="own-head"><b>UNDERTAKING SUBMITTED FOR OWN VEHICLE</b></th></tr>
			{%- endif %}
			<tr>
				{%- if tall and not seen.own %}
				<td rowspan="{{ n_own }}" class="own-label"><svg width="24" height="190" xmlns="http://www.w3.org/2000/svg"><text transform="translate(9,95) rotate(-90)" text-anchor="middle" font-family="Arial, Helvetica, sans-serif" font-size="9" font-weight="bold" fill="#111">UNDERTAKING SUBMITTED FOR OWN</text><text transform="translate(22,95) rotate(-90)" text-anchor="middle" font-family="Arial, Helvetica, sans-serif" font-size="9" font-weight="bold" fill="#111">VEHICLE</text></svg></td>
				{%- elif not tall %}
				<td class="c"></td>
				{%- endif %}
				<td class="{{ 'c' if bal else 'l' }}">{{ row.vehicle_no }}</td>
				<td class="{{ cl_n }}">{{ ("%.2f" | format(row.qty or 0)).rstrip("0").rstrip(".") }}</td>
				<td class="{{ cl_n }}">{{ "%.2f" | format(row.amount or 0) }}</td>
				<td class="c"></td>
				<td class="c"></td>
				<td class="c">OWN VEHICLE</td>
			</tr>
			{%- set seen.own = true %}
			{%- else %}
			<tr class="sub">
				<td class="nb"></td><td class="nb c"><b>TOTAL</b></td><td class="nb {{ cl_n }}"><b>{{ ("%.2f" | format(it.q or 0)).rstrip("0").rstrip(".") }}</b></td><td class="nb {{ cl_n }}"><b>{{ "%.2f" | format(it.a or 0) }}</b></td><td class="nb" colspan="3"></td>
			</tr>
			{%- endif %}
			{%- endfor %}
			{%- if loop.last %}
			<tr class="sub">
				<td class="nb"></td><td class="nb c"><b>G.TOTAL</b></td><td class="nb {{ cl_n }}"><b>{{ ("%.2f" | format((h_qty or 0) + (o_qty or 0))).rstrip("0").rstrip(".") }}</b></td><td class="nb {{ cl_n }}"><b>{{ "%.2f" | format((h_amt or 0) + (o_amt or 0)) }}</b></td><td class="nb" colspan="3"></td>
			</tr>
			<tr class="sub">
				<td class="nb"></td><td class="nb c"><b>TOTAL VOUCHER</b></td><td class="nb {{ cl_n }}"><b>{{ doc.total_vouchers or 0 }} NOS</b></td><td class="nb" colspan="4"></td>
			</tr>
			<tr class="sign-gap"><td class="nb" colspan="7"></td></tr>
			<tr class="signs">
				<td class="nb sg" colspan="3" style="text-align:left"><b>SIGNATURE OF AUTHORISED OFFICER</b></td><td class="nb" colspan="1"></td><td class="nb sg" colspan="3" style="text-align:right"><b>SIGNATURE OF CUSTOM MILLER</b></td>
			</tr>
			{%- endif %}
		</tbody>
	</table>
</div>
{%- endfor %}

css:
.print-format { max-width: none; padding: 0; margin: 0; font-size: 10px; }
.vws { font-family: Arial, Helvetica, sans-serif; color: #111; }
.vws-break { page-break-after: always; }
.vws table { width: 94%; margin: 0 auto; border-collapse: collapse; table-layout: fixed; }
.vws th, .vws td { border: 1px solid #222; padding: 4px 5px; color: #111 !important; font-size: 10px; line-height: 1.3; word-wrap: break-word; vertical-align: middle; }
.vws thead { display: table-header-group; }
.vws thead th { background: #fff; font-weight: bold; text-align: center; text-transform: uppercase; }
.vws .title { font-size: 11px; padding: 9px 6px; line-height: 1.5; text-align: center; }
.vws .mill { font-size: 11px; padding: 5px 6px; text-align: center; }
.vws .head th { font-size: 9.5px; padding: 5px 4px; }
.vws td.c { text-align: center; }
.vws td.l { text-align: left; }
.vws td.r { text-align: right; }
.vws .total td { font-weight: bold; }
.vws tr, .vws td, .vws th { page-break-inside: avoid; }
.vws th, .vws th b { font-weight: 700 !important; }
.vws td.nb, .vws .nb { border: 0; }
.print-format .vws .sub td { font-size: 10px; padding: 2px 5px !important; line-height: 1.25; }
.vws .own-head { font-size: 10px; text-align: center; padding: 5px; }
.vws .own-label { vertical-align: middle; padding: 0; }
.vws .sign-gap td { height: 22mm; }
.vws .sg { font-size: 10px; padding-top: 4px; }

.print-format { max-width: none; padding: 0; margin: 0; font-size: 12px; }
.dv { font-family: Arial, Helvetica, sans-serif; color: #111; height: 170mm; padding: 8mm 4mm 0 4mm; overflow: hidden; }
.dv-break { page-break-after: always; }
.dv-cut { border-top: 1px dashed #888; margin: 0 0 4mm 0; }
.dv .c { text-align: center; }
.dv .t1 { font-size: 13px; text-decoration: underline; margin: 0 0 9mm 0; }
.dv .t2 { font-size: 13px; font-weight: bold; margin: 0 0 3mm 0; }
.dv .t3 { font-size: 12px; line-height: 1.5; margin: 0; }
.dv .t4 { font-size: 13px; font-weight: bold; margin: 3mm 0 0 0; }
.dv table { width: 100%; border-collapse: collapse; }
.dv td { padding: 0; vertical-align: bottom; font-size: 12px; color: #111 !important; }
.dv .gap { height: 9mm; }
.dv .line { border-bottom: 1px solid #222; font-size: 14px; padding: 0 3px; height: 10mm; }
.dv .lbl { white-space: nowrap; padding-right: 4px; }
.dv .sign { font-size: 12px; }
.dv .sign-space { height: 28mm; }
.dv .cash { position: relative; display: inline-block; }
.dv .tick { position: absolute; left: 0; top: -13px; width: 100%; text-align: center; font-size: 15px; font-weight: bold; }
.dv .org { font-size: 11px; text-align: right; }
.dv tr { page-break-inside: avoid; }
